import React, { useState } from 'react';
import { useDispatch } from 'react-redux';
import { addToCart } from '../features/cartSlice';
import { useNavigate } from 'react-router-dom';
import ProductCard from '../components/ProductCard';

// Example product data
const products = [
  { id: 1, name: 'Laptop', price: 999, image: 'https://via.placeholder.com/150' },
  { id: 2, name: 'Phone', price: 499, image: 'https://via.placeholder.com/150' },
  { id: 3, name: 'Headphones', price: 199, image: 'https://via.placeholder.com/150' },
  { id: 4, name: 'Smartwatch', price: 299, image: 'https://via.placeholder.com/150' },
];

function Home() {
  const dispatch = useDispatch();
  const navigate = useNavigate();
  const [search, setSearch] = useState('');

  // Filter products by search term
  const filteredProducts = products.filter(prod =>
    prod.name.toLowerCase().includes(search.toLowerCase())
  );

  return (
    <div style={{ maxWidth: 900, margin: '0 auto', padding: 24 }}>
      <h1>Products</h1>
      <input
        type="text"
        placeholder="Search products..."
        value={search}
        onChange={e => setSearch(e.target.value)}
        style={{
          padding: 8,
          width: '100%',
          maxWidth: 400,
          marginBottom: 24,
          borderRadius: 4,
          border: '1px solid #ccc'
        }}
      />
      <div
        style={{
          display: 'grid',
          gridTemplateColumns: 'repeat(auto-fit, minmax(200px, 1fr))',
          gap: 24,
        }}
      >
        {filteredProducts.length === 0 ? (
          <p>No products found.</p>
        ) : (
          filteredProducts.map(prod => (
            <ProductCard
              key={prod.id}
              product={prod}
              onAddToCart={() => {
                dispatch(addToCart(prod));
                navigate('/cart');
              }}
            />
          ))
        )}
      </div>
    </div>
  );
}

export default Home;
